    /**
     * Tests updating a Policy.
     *
     * @return    Policy
     */
    public Policy testUpdate() throws Throwable {
    LOGGER.info( "PolicyTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Policy." );

    StringBuilder msg = new StringBuilder( "Failed to update a Policy : " );
    Policy entity = null;

    try {
        UpdatePolicyCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setPolicyId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Policy." );

        entity = service.updatePolicy( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Policy - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

