    /**
     * Tests getting all Policys.
     *
     * @return    Collection
     */
    public List<Policy> testGetAll() throws Throwable {
    LOGGER.info( "PolicyTest:testGetAll() - Retrieving Collection of Policys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Policy : " );
    List<Policy> collection  = null;

    try {
        // call the static get method on the PolicyService
        collection = service.getAllPolicy();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Policy currEntity  = null;
            Iterator<Policy> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPolicyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

